<script lang="ts">
  import {onMount} from 'svelte';
  import {api} from '../api';
  import RecordedVeterans from './RecordedVeterans.svelte';
  import {statColors} from '../sandbox/stat-colors';
  import type {ReferenceData} from '../data/reference';
  import UmaPortrait from './SimulatorPortrait.svelte';
  import {uid,type Library,type UmaBuild,type UmaFolder} from '../sandbox/model';
  import {emptyFilter,libraryIndex,filterLibrary,inLibraryView,parseTags,duplicateUma,exportUmas} from '../sandbox/library';
  import LibraryIcon from './LibraryIcon.svelte';
  import LibraryDialog from './LibraryDialog.svelte';
  export let library:Library;
  export let reference:ReferenceData;
  export let picker=false;
  export let view='unfiled';
  export let onEdit:(uma:UmaBuild)=>void=()=>{};
  export let onChoose:(uma:UmaBuild)=>void;
  export let canAdd=true;
  export let onMutate:(body:unknown)=>Promise<void>=async()=>{};
  export let onExport:(name:string,value:unknown)=>void=()=>{};
  let filter=emptyFilter(),selected:string[]=[],working=false,failure='',moveTo='',tagInput='',tagAction:'addTags'|'removeTags'='addTags';
  let folderDraft:UmaFolder|null=null,deleteUma:UmaBuild|null=null,deleteFolder:UmaFolder|null=null,dragging:string[]=[];
  $: filter.view=view;
  $: folders=[...(library.folders??[])].sort((a,b)=>a.name.localeCompare(b.name));
  $: rows=libraryIndex(library,reference);
  $: shown=filterLibrary(rows,filter,folders);
  $: selected=selected.filter(id=>shown.some(r=>r.uma.id===id));
  $: characters=[...new Map(rows.map(r=>[r.uma.charaId,r.character])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));
  $: outfits=[...new Map(rows.filter(r=>!filter.character||r.uma.charaId===Number(filter.character)).map(r=>[r.uma.cardId,r.outfit])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));
  $: allTags=[...new Map(library.umas.flatMap(u=>u.tags??[]).map(t=>[t.toLocaleLowerCase(),t])).values()].sort((a,b)=>a.localeCompare(b));
  $: activeFolder=folders.find(f=>view===`folder:${f.id}`);
  $: if(view.startsWith('folder:')&&!folders.some(f=>view===`folder:${f.id}`))view='unfiled';
  const sections=[['unfiled','Dorm','folder'],['veterans','Veterans','race'],['all','All Umas','grid'],['favorites','Favorites','star'],['archive','Archive','archive']];
  let veteranCount:number|null=null;
  onMount(()=>{let stopped=false;void api<{count:number}>('veterans?summary=1').then(value=>{if(!stopped)veteranCount=value.count;}).catch(()=>{});return()=>{stopped=true;};});
  const colors=['#8bc783','#7cb9ed','#be98ee','#f1ad63','#ee8db8','#76d5cb'];
  const icons=['folder','race','trophy','star','flask','heart'];
  const stats=['speed','stamina','power','guts','wisdom'] as const;
  const statLabels=['Speed','Stamina','Power','Guts','Wit'];
  $: counts=Object.fromEntries([...sections.map(s=>s[0]),...folders.map(f=>`folder:${f.id}`)].map(name=>[name,library.umas.filter(u=>inLibraryView(u,name,folders)).length]));
  function navigate(next:string){view=next;selected=[];}
  async function mutate(body:unknown){working=true;failure='';try{await onMutate(body);return true;}catch(e){failure=String(e);return false;}finally{working=false;}}
  async function bulk(patch:unknown,ids=selected){return mutate({collection:'umas',action:'bulk',ids,patch});}
  async function saveFolder(){if(folderDraft&&await mutate({collection:'folders',record:folderDraft})){view=`folder:${folderDraft.id}`;folderDraft=null;}}
  function toggle(id:string){selected=selected.includes(id)?selected.filter(s=>s!==id):[...selected,id];}
  function startDrag(e:DragEvent,uma:UmaBuild){if(picker||working)return;e.dataTransfer?.setData('application/x-umalytics-umas',JSON.stringify(selected.includes(uma.id)?selected:[uma.id]));if(e.dataTransfer)e.dataTransfer.effectAllowed='move';dragging=selected.includes(uma.id)?selected:[uma.id];}
  function dragOver(e:DragEvent){if(dragging.length){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';}}
  async function drop(e:DragEvent,folderId:string){if(!dragging.length)return;e.preventDefault();const ids=dragging;dragging=[];await bulk({folderId},ids);}
  async function duplicate(uma:UmaBuild){const copy=duplicateUma(uma);if(await mutate({collection:'umas',record:copy}))onEdit(copy);}
  function clearFilters(){filter={...emptyFilter(),view};}
</script>
<div class="library-layout" class:picker aria-busy={working}>
  <nav class="folders" aria-label={picker?'Load Uma folders':'Uma folders'}>
    {#each sections as [key,label,icon]}
      <button class:current={view===key} aria-current={view===key?'page':undefined} onclick={()=>navigate(key)} ondragover={key==='unfiled'?dragOver:undefined} ondrop={key==='unfiled'?e=>drop(e,''):undefined} class:drop-target={key==='unfiled'&&dragging.length>0}><LibraryIcon name={icon}/><span>{label}</span><small>{key==='veterans'?veteranCount??'—':counts[key]}</small></button>
    {/each}
    <div class="folder-heading"><span>Folders</span>{#if !picker}<button aria-label="New folder" title="New folder" onclick={()=>folderDraft={id:uid(),name:'',color:colors[0],icon:'folder'}}>＋</button>{/if}</div>
    {#each folders as folder}
      <div class="folder-row" style={`--folder-color:${folder.color}`}>
        <button class:current={view===`folder:${folder.id}`} class:drop-target={dragging.length>0} aria-current={view===`folder:${folder.id}`?'page':undefined} onclick={()=>navigate(`folder:${folder.id}`)} ondragover={dragOver} ondrop={e=>drop(e,folder.id)}><span class="folder-icon"><LibraryIcon name={folder.icon}/></span><span>{folder.name}</span><small>{counts[`folder:${folder.id}`]}</small></button>
        {#if !picker}<button class="folder-edit" aria-label={`Edit folder ${folder.name}`} title={`Edit ${folder.name}`} onclick={()=>folderDraft={...folder}}><LibraryIcon name="edit" size={13}/></button>{/if}
      </div>
    {/each}
    {#if !folders.length&&!picker}<button class="new-folder" onclick={()=>folderDraft={id:uid(),name:'',color:colors[0],icon:'folder'}}>＋ New folder</button>{/if}
  </nav>
  <div class="library-main">
    {#if view==='veterans'}
      <RecordedVeterans {reference} {picker} {onChoose} onCopy={async uma=>{await onMutate({collection:'umas',record:uma});}} onCount={count=>veteranCount=count}/>
    {:else}
    <div class="library-tools"><input type="search" aria-label={picker?'Search Umas to load':'Search saved Umas'} placeholder="Search Umas, skills, tags, memos…" bind:value={filter.query}/><select aria-label="Sort Umas" bind:value={filter.sort}><option value="recent">Recently edited</option><option value="name">Name</option><option value="character">Character</option><option value="sp">SP cost</option>{#each stats as stat}<option value={stat}>{stat==='wisdom'?'Wit':stat[0].toUpperCase()+stat.slice(1)}</option>{/each}</select></div>
    <div class="filter-row"><select aria-label="Filter character" bind:value={filter.character} onchange={()=>filter.outfit=''}><option value="">All characters</option>{#each characters as [id,name]}<option value={String(id)}>{name}</option>{/each}</select><select aria-label="Filter outfit" bind:value={filter.outfit}><option value="">All outfits</option>{#each outfits as [id,name]}<option value={String(id)}>{name}</option>{/each}</select><select aria-label="Filter tag" bind:value={filter.tag}><option value="">All tags</option>{#each allTags as tag}<option>{tag}</option>{/each}</select>{#if filter.query||filter.character||filter.outfit||filter.tag}<button class="text-button" onclick={clearFilters}>Clear filters</button>{/if}</div>
    {#if failure}<p class="library-error" role="alert">{failure}</p>{/if}
    <div class="library-count"><span>{activeFolder?.name??sections.find(s=>s[0]===view)?.[1]} <small>· {shown.length}</small></span>{#if !picker&&shown.length}<label><input type="checkbox" aria-label="Select visible Umas" checked={selected.length===shown.length} indeterminate={selected.length>0&&selected.length<shown.length} onchange={e=>selected=e.currentTarget.checked?shown.map(r=>r.uma.id):[]}/>Select visible</label>{/if}</div>
    {#if selected.length&&!picker}<div class="bulk-actions"><strong>{selected.length} selected</strong><select aria-label="Move selected Umas" bind:value={moveTo}><option value="">Move to…</option><option value="unfiled">Dorm</option>{#each folders as f}<option value={f.id}>{f.name}</option>{/each}</select><button disabled={working||!moveTo} onclick={async()=>{if(await bulk({folderId:moveTo==='unfiled'?'':moveTo}))moveTo='';}}>Move</button><button disabled={working} onclick={()=>bulk({favorite:true})}>★ Favorite</button><button disabled={working} onclick={()=>bulk({favorite:false})}>Unfavorite</button><button disabled={working} onclick={()=>bulk({archived:view!=='archive'})}>{view==='archive'?'Restore':'Archive'}</button><button onclick={()=>onExport('Umas',exportUmas(library,selected))}>Export</button><div class="bulk-tags"><select aria-label="Tag action" bind:value={tagAction}><option value="addTags">Add tags</option><option value="removeTags">Remove tags</option></select><input aria-label="Tags for selected Umas" placeholder="Tags, separated by commas" bind:value={tagInput}/><button disabled={working||!tagInput.trim()} onclick={async()=>{if(await bulk({[tagAction]:parseTags(tagInput)}))tagInput='';}}>Apply</button></div></div>{/if}
    <div class="uma-cards">
      {#each shown as row (row.uma.id)}{@const uma=row.uma}{@const folder=folders.find(f=>f.id===uma.folderId)}
        <article class="uma-card" class:selected={selected.includes(uma.id)} draggable={!picker&&!working} ondragstart={e=>startDrag(e,uma)} ondragend={()=>dragging=[]}>
          <div class="card-heading">{#if !picker}<input type="checkbox" aria-label={`Select ${uma.name}`} checked={selected.includes(uma.id)} onchange={()=>toggle(uma.id)}/>{/if}<UmaPortrait {uma} size={44}/><div class="card-name"><h3>{uma.name}</h3><small>{row.outfit}</small></div><div class="card-controls">{#if !picker}<button class="favorite" class:on={uma.favorite} disabled={working} aria-label={`${uma.favorite?'Unfavorite':'Favorite'} ${uma.name}`} aria-pressed={!!uma.favorite} title={uma.favorite?'Unfavorite':'Favorite'} onclick={()=>bulk({favorite:!uma.favorite},[uma.id])}><LibraryIcon name="star"/></button><button class="delete" disabled={working} aria-label={`Delete ${uma.name}`} title="Delete Uma" onclick={()=>deleteUma=uma}><LibraryIcon name="trash"/></button>{:else if uma.favorite}<span class="favorite on"><LibraryIcon name="star"/></span>{/if}</div></div>
          {#if uma.memo}<p class="memo" title={uma.memo}>{uma.memo}</p>{/if}
          {#if folder||uma.tags?.length}<div class="tags">{#if folder}<span class="folder-tag" style={`--folder-color:${folder.color}`}><LibraryIcon name={folder.icon} size={12}/>{folder.name}</span>{/if}{#each uma.tags??[] as tag}<button onclick={()=>filter.tag=tag}>{tag}</button>{/each}</div>{/if}
          <div class="mini-stats">{#each stats as key,i}<span style={`--stat:${statColors[key]}`} title={statLabels[i]}><img src={`./career/support-type-${i}.png`} alt={statLabels[i]}/><strong>{uma.stats[key]??'—'}</strong></span>{/each}</div>
          <div class="card-details"><small>{uma.skills.length} skills · {row.cost.total.toLocaleString()} SP{row.cost.unknown?' + ?':''}</small>{#if uma.variantOf}<small title={library.umas.find(u=>u.id===uma.variantOf)?.name??'Original build'}>Variant</small>{/if}</div>
          <div class="card-actions">{#if picker}<button class="primary" onclick={()=>onChoose(uma)}>Load Uma</button>{:else}<button onclick={()=>onEdit(uma)}>Edit</button><button disabled={!canAdd} onclick={()=>onChoose(uma)}>Add to race</button><details class="card-more"><summary aria-label={`More actions for ${uma.name}`} title="More actions">•••</summary><div><button disabled={working} onclick={()=>duplicate(uma)}><LibraryIcon name="copy" size={15}/><span>Duplicate as variant</span></button><button onclick={()=>onExport(uma.name,exportUmas(library,[uma.id]))}><LibraryIcon name="export" size={15}/><span>Export</span></button><button disabled={working} onclick={()=>bulk({archived:!uma.archived},[uma.id])}><LibraryIcon name="archive" size={15}/><span>{uma.archived?'Restore':'Archive'}</span></button></div></details>{/if}</div>
        </article>
      {/each}
    </div>
    {#if !shown.length}<div class="empty-library"><LibraryIcon name={view==='archive'?'archive':'folder'} size={32}/><p>{library.umas.length?'No Umas here.':'No saved Umas yet.'}</p>{#if filter.query||filter.character||filter.outfit||filter.tag}<button onclick={clearFilters}>Clear filters</button>{/if}</div>{/if}
    {/if}
  </div>
</div>
{#if folderDraft}<LibraryDialog title={folders.some(f=>f.id===folderDraft?.id)?'Edit folder':'New folder'} onClose={()=>{if(!working)folderDraft=null;}}><form onsubmit={e=>{e.preventDefault();void saveFolder();}}><label class="field">Name<input aria-label="Folder name" required maxlength="60" bind:value={folderDraft.name}/></label><div class="choices" aria-label="Folder icon">{#each icons as icon}<button type="button" class:chosen={folderDraft.icon===icon} aria-label={`${icon} icon`} aria-pressed={folderDraft.icon===icon} onclick={()=>{if(folderDraft)folderDraft.icon=icon;}}><LibraryIcon name={icon}/></button>{/each}</div><div class="choices" aria-label="Folder color">{#each colors as color,i}<button type="button" class="color" class:chosen={folderDraft.color===color} aria-label={['Green','Blue','Purple','Orange','Pink','Teal'][i]} aria-pressed={folderDraft.color===color} style:background={color} onclick={()=>{if(folderDraft)folderDraft.color=color;}}></button>{/each}</div>{#if failure}<p class="library-error" role="alert">{failure}</p>{/if}<div class="dialog-actions">{#if folders.some(f=>f.id===folderDraft?.id)}<button type="button" class="delete" disabled={working} onclick={()=>{deleteFolder=folderDraft;folderDraft=null;}}><LibraryIcon name="trash"/>Delete folder</button>{/if}<button type="button" disabled={working} onclick={()=>folderDraft=null}>Cancel</button><button class="primary" disabled={working||!folderDraft.name.trim()}>Save folder</button></div></form></LibraryDialog>{/if}
{#if deleteUma}<LibraryDialog title="Delete Uma?" onClose={()=>{if(!working)deleteUma=null;}}><p class="confirm-copy">Delete <strong>{deleteUma.name}</strong> from your library? Saved race setups and results will stay intact.</p>{#if failure}<p class="library-error" role="alert">{failure}</p>{/if}<div class="dialog-actions"><button disabled={working} onclick={()=>deleteUma=null}>Cancel</button><button class="delete confirm-delete" disabled={working} onclick={async()=>{if(deleteUma&&await mutate({collection:'umas',remove:deleteUma.id}))deleteUma=null;}}><LibraryIcon name="trash"/>Delete Uma</button></div></LibraryDialog>{/if}
{#if deleteFolder}<LibraryDialog title="Delete folder?" onClose={()=>{if(!working)deleteFolder=null;}}><p class="confirm-copy">Delete <strong>{deleteFolder.name}</strong>? Its Umas will move to Dorm.</p>{#if failure}<p class="library-error" role="alert">{failure}</p>{/if}<div class="dialog-actions"><button disabled={working} onclick={()=>deleteFolder=null}>Cancel</button><button class="delete confirm-delete" disabled={working} onclick={async()=>{if(deleteFolder&&await mutate({collection:'folders',remove:deleteFolder.id}))deleteFolder=null;}}><LibraryIcon name="trash"/>Delete folder</button></div></LibraryDialog>{/if}
<style>


  .library-layout{display:grid;grid-template-columns:180px minmax(0,1fr);gap:24px;align-items:start}.folders{display:grid;gap:4px;position:sticky;top:12px;min-width:0}.folders>button,.folder-row>button:first-child{display:flex;align-items:center;gap:10px;text-align:left;border:0;background:transparent;width:100%;padding:10px;color:var(--muted);min-width:0}.folders button>span:not(.folder-icon){flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.folders button small{font-size:11px;opacity:.7;font-weight:400}.folders button.current{background:var(--accent-soft);color:var(--text)}.folder-heading{display:flex;justify-content:space-between;align-items:center;margin:15px 8px 4px;font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.folder-heading button{background:transparent;border:0;padding:1px 6px;font-size:20px;color:var(--muted)}.folder-row{display:flex;min-width:0}.folder-row>button:first-child{flex:1}.folder-icon{color:var(--folder-color);display:flex}.folder-edit{padding:6px;border:0;background:transparent;opacity:.45}.folder-edit:hover{opacity:1}.folders .new-folder{border:1px dashed var(--border);font-size:12px;justify-content:center}.folders .drop-target{outline:1px dashed var(--accent)}.library-main{min-width:0;display:grid;gap:15px}.library-tools{display:flex;gap:9px}.library-tools input{flex:1;min-width:100px}.library-tools select{width:150px}.filter-row{display:flex;gap:8px;flex-wrap:wrap}.filter-row select{max-width:210px;flex:1;font-size:11px;padding:7px}.filter-row .text-button{padding:4px 8px;background:transparent;border:0;font-size:11px}.library-count{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:13px}.library-count small,.library-count label{font-size:11px;color:var(--muted)}.library-count label{display:flex;align-items:center;gap:6px}.uma-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:14px;align-items:start}.uma-card{background:var(--panel);border:1px solid var(--border);border-radius:10px;padding:16px;display:flex;flex-direction:column;gap:13px;min-width:0;position:relative}.uma-card.selected{border-color:var(--accent)}.card-heading{display:flex;align-items:center;gap:9px;min-height:42px}.card-controls{display:flex;gap:3px;align-self:flex-start;margin-left:auto;flex:none}.card-controls button{border:0;background:transparent;padding:5px;display:flex}.favorite{color:var(--muted)}.favorite.on{color:#e6bd60}.favorite.on :global(svg){fill:#e6bd6030}.delete{color:#ec7777}.delete:hover{background:#e45a5a18}.card-name{flex:1;min-width:0}.card-name h3{font-size:15px;margin:0 0 5px;overflow-wrap:anywhere}.card-name small{display:block;font-size:11px;color:var(--muted);line-height:1.4;overflow-wrap:anywhere}.memo{color:var(--muted);font-size:12px;line-height:1.5;margin:0;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;white-space:pre-wrap}.tags{display:flex;flex-wrap:wrap;gap:5px}.tags button,.tags>span{font-size:10px;padding:3px 6px;border:1px solid var(--border);border-radius:4px;background:var(--bg);font-weight:400;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tags .folder-tag{display:flex;align-items:center;gap:4px;color:var(--folder-color);border-color:color-mix(in srgb,var(--folder-color) 30%,var(--border))}.mini-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:5px;text-align:center;font-variant-numeric:tabular-nums;font-size:14px}.mini-stats span{display:grid;justify-items:center;gap:4px;padding:5px 0;border-bottom:2px solid var(--stat);background:color-mix(in srgb,var(--stat) 6%,transparent);border-radius:4px 4px 0 0}.mini-stats img{width:22px;height:22px;object-fit:contain}.mini-stats strong{font-size:15px;font-weight:550}.card-details{display:flex;justify-content:space-between;gap:6px;color:var(--muted);font-size:12px}.card-actions{display:flex;gap:7px;margin-top:auto}.card-actions>button{font-size:12px;white-space:nowrap}.card-actions>button:nth-child(2){flex:1}.card-more{margin-left:auto;position:relative}.card-more summary{cursor:pointer;list-style:none;padding:9px 7px;color:var(--muted);border-radius:5px;letter-spacing:1px}.card-more summary::-webkit-details-marker{display:none}.card-more[open]{z-index:5}.card-more>div{position:absolute;top:100%;right:0;width:185px;padding:5px;background:var(--panel);border:1px solid var(--border);box-shadow:0 6px 20px #0005;border-radius:8px}.card-more button{display:grid;grid-template-columns:15px minmax(0,1fr);align-items:center;justify-content:start;justify-items:start;gap:8px;white-space:normal;line-height:1.4;text-align:left;border:0;background:transparent;width:100%;font-size:11px;padding:10px}.card-more button:hover{background:var(--accent-soft)}input,select{min-width:0;padding:9px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--text);font:inherit;font-size:12px}input[type=checkbox]{accent-color:var(--accent);width:14px;height:14px;margin:0;flex:none}.bulk-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap;background:var(--accent-soft);border:1px solid var(--border);padding:10px;border-radius:8px;font-size:11px}.bulk-actions strong{font-size:12px;margin-right:6px}.bulk-actions button,.bulk-actions select,.bulk-actions input{font-size:11px;padding:7px}.bulk-tags{display:flex;gap:6px;flex-wrap:wrap;width:100%}.bulk-tags input{flex:1;min-width:120px}.empty-library{text-align:center;padding:50px 10px;color:var(--muted);font-size:13px}.library-error{color:#ed8e86;font-size:12px;overflow-wrap:anywhere}.field{display:grid;gap:7px;font-size:12px;color:var(--muted)}.field input{font-size:14px}.choices{display:flex;gap:10px;margin-top:16px}.choices button{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--border);padding:6px;background:var(--bg)}.choices button.chosen{outline:2px solid var(--accent);outline-offset:2px}.choices .color{width:26px;height:26px;border-radius:50%;border:0}.dialog-actions{display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-top:22px;flex-wrap:wrap}.dialog-actions button{display:flex;gap:6px;align-items:center;font-size:12px}.dialog-actions .delete:first-child:not(:last-child){margin-right:auto}.confirm-delete{background:#b8383820;border-color:#d85e5e77}.confirm-copy{font-size:13px;line-height:1.6;margin:0}.picker{grid-template-columns:140px minmax(0,1fr);gap:16px}.picker .uma-cards{grid-template-columns:repeat(auto-fill,minmax(220px,1fr))}.picker .uma-card{padding:12px;gap:10px}.picker .card-actions button{width:100%}.picker .folders{position:static}.picker .memo{display:none}.picker .filter-row select{max-width:160px}@media(max-width:760px){.library-layout,.picker{grid-template-columns:1fr}.folders{position:static;display:flex;flex-wrap:wrap;gap:4px}.folders>button,.folder-row{width:auto;max-width:200px}.folders>button{width:auto}.folder-heading{margin:0 4px;align-self:center}.folder-edit{display:none}.library-tools{flex-wrap:wrap}.library-tools input{min-width:150px}.filter-row select{max-width:100%;min-width:100px}.uma-cards{grid-template-columns:repeat(auto-fill,minmax(235px,1fr))}}
</style>
